import hashlib, json, os, stat
manifest=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST']))
root=os.environ['STAMPED_JUDGE_TARGET']
prefix='content/workspace/'
expected={e['path'][len(prefix):]:e for e in manifest['entries'] if e['path'].startswith(prefix)}
actual={}
for base,dirs,files in os.walk(root,topdown=True,followlinks=False):
    for name in list(dirs)+files:
        p=os.path.join(base,name); rel=os.path.relpath(p,root)
        try: st=os.lstat(p)
        except OSError: continue
        if stat.S_ISLNK(st.st_mode): kind='symlink'; payload=os.readlink(p)
        elif stat.S_ISDIR(st.st_mode): kind='directory'; payload=None
        elif stat.S_ISREG(st.st_mode): kind='file'; payload=hashlib.sha256(open(p,'rb').read()).hexdigest()
        else: kind='other'; payload=None
        actual[rel]=(kind,stat.S_IMODE(st.st_mode),payload)
        if kind=='symlink' and name in dirs: dirs.remove(name)
mismatches=[]; operational_metadata=[]
for rel,e in expected.items():
    got=actual.get(rel)
    same=got is not None and got[0]==e['kind'] and got[1]==e.get('mode')
    if same and e['kind']=='file': same=got[2]==e.get('sha256')
    if same and e['kind']=='symlink': same=got[2]==e.get('target')
    if not same:
        row={'path':rel,'expected_kind':e['kind'],'actual':got}
        if rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'} and got and got[0]=='file': operational_metadata.append(row)
        else: mismatches.append(row)
for rel,got in actual.items():
