        row={'path':rel,'actual':got}
        if rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'} and got[0]=='file': operational_metadata.append(row)
        else: mismatches.append(row)
report={'canonical_capture_sha256':json.load(open(os.path.join(os.environ['STAMPED_JUDGE_OUTPUT'],'judge-target.json')))['capture']['sha256'],'baseline_operational_manifest_sha256':json.load(open(os.environ['STAMPED_JUDGE_OUTPUT']+'/judge-target.json'))['operational_capture']['sha256'],'entry_count':len(expected),'mismatches':mismatches,'operational_metadata_changes':operational_metadata,'integrity':'match except classified operational metadata' if not mismatches else 'mismatch'}
out=os.path.join(os.environ['STAMPED_JUDGE_OUTPUT'],'integrity','operational-integrity.json'); os.makedirs(os.path.dirname(out),exist_ok=True); json.dump(report,open(out,'w'),indent=2)
print(json.dumps({'integrity':report['integrity'],'entry_count':len(expected),'mismatches':len(mismatches),'operational_metadata_changes':len(operational_metadata),'report':out}))
